// Fragmente ilustrative deterministe (nu sunt secvențele complete din UniProt)
function hashStr(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function rng(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
// Secvențe reale din UniProt (când sunt încărcate); altfel fragment ilustrativ determinist
const SEQ=(typeof PD_SEQ==='object'&&PD_SEQ)||{};
function hasRealSeq(g){return !!SEQ[g]}
// Ținte pe care, în logica lui Sternheimer, ai vrea să le scazi: primesc implicit codul de inhibare
const INHIB_DEF=new Set(['TNF','IL6','IL4','IL13','FCER1A','HRH1','IL17A','IL23A','PCSK9','HMGCR','ACE','AGT','REN','SOST','SNCA','LRRK2','APP','MAPT','ATP4A','CALCA','MTOR','PDE5A','TEM1','KPC2','NDM1','MECA','ACRB','LASR','CSGA','BCPG1','AVR3A','NOSSWP']);
function isInhib(g){const m=S.modes||(S.modes={}); return m[g]!=null?m[g]==='i':INHIB_DEF.has(g)}
function seqFor(gene){
  if(SEQ[gene]) return SEQ[gene];
  const r=rng(hashStr(gene+'|'+(T[gene]?T[gene][1]:'')));
  const len=28+Math.floor(r()*14); let s='M';
  for(let i=1;i<len;i++) s+=AA_LIST[Math.floor(r()*20)];
  return s;
}

