const GRP_SHORT={'Afecțiuni frecvente':'Afecțiuni','Somn & Calm':'Somn','Minte & Emoții':'Minte','Corp & Mișcare':'Corp','Imunitate & Respirație':'Imunitate','Metabolism & Organe':'Organe','Intimitate & Hormoni':'Intim','Apărare & Boli':'Apărare','Legume & Cartof':'Legume','Pomi & Viță':'Pomi & Vie','Creștere & Recoltă':'Recoltă','Secetă, Căldură & Frig':'Vreme grea','Vaci & Lapte':'Vaci','Câini & Pisici':'Câini & Pisici','Stres & Transport':'Calm'};
const GRP_ICON={om:['','moon','brain','body','shield','heart','hearts','child','time','pulse'],plante:['','shield','veg','tree','wheat','flower','sun'],insecte:['','insecte','flower','ban'],animale:['','cow','pig','egg','animale','calm']};
S.sub='custom';
function setSub(v){S.sub=v; document.querySelectorAll('[data-sub]').forEach(b=>b.classList.toggle('sel',b.dataset.sub===v));
  $('sub-custom').classList.toggle('hidden',v!=='custom'); $('sub-pre').classList.toggle('hidden',v!=='pre'); if(v==='custom'&&S.dom!=='om') renderOpts()}
document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>setSub(b.dataset.sub));
function optGenes(){
  if(S.dom!=='om'){const o=[]; PRESETS.filter(p=>p.dom===S.dom).forEach(p=>p.g.forEach(g=>{if(!o.includes(g)) o.push(g)})); return o}
  if(!S.part) return [];
  const sex=S.sex||'U', o=[]; const add=g=>{if(T[g]&&!o.includes(g)) o.push(g)};
  (S.part[1].length?S.part[1]:SEX_T[sex]).forEach(add);
  if(S.act) (S.act==='hormon'?SEX_T[sex]:ACTIONS[S.act].t).forEach(add);
  return o;
}
function customStack(){
  if(!S.stack||!S.stack.custom){ const nm=S.dom!=='om'?tr(DOMS[S.dom].n)+' '+L('personal','custom'):shortName((S.act?ACT_SHORT[S.act]+' ':'')+(S.part?S.part[0]:L('Stiva mea','My stack')));
    S.stack={name:nm,color:'#22d3ee',genes:[],tags:[L('Custom','Custom')],custom:true} }
  return S.stack;
}
function toggleOpt(g){
  const st=customStack(), i=st.genes.indexOf(g);
  if(i>=0){ st.genes.splice(i,1); toast(L('Scos din stivă: ','Removed from stack: ')+g) } else { st.genes.push(g); toast(L('Adăugat în stivă: ','Added to stack: ')+g) }
  if(st.genes.length) setStack(st); else {S.stack=null; $('sec-stack').classList.add('hidden'); showBar()}
  renderOpts();
}
function renderOpts(){
  const gs=optGenes(), sec=$('sec-opts'), row=$('opt-row'); sec.classList.toggle('hidden',!gs.length); row.innerHTML='';
  const inS=g=>S.stack&&S.stack.custom&&S.stack.genes.includes(g);
  gs.forEach(g=>{const c=document.createElement('div'); c.className='ocard'+(inS(g)?' in':'');
    c.innerHTML='<b>'+g+'</b><div class="on">'+esc(T[g][0])+'</div><div class="od">'+esc(D[g]||'')+'</div>';
    const q=document.createElement('button'); q.className='small ob oq'; q.textContent='?'; q.setAttribute('aria-label',L('Ce face ','What does ')+g);
    q.onclick=()=>openSheet({name:g+' · '+T[g][0],color:'#22d3ee',genes:[g],syn:D[g]||'',mood:'mediu'});
    const a=document.createElement('button'); a.className='small ob oa'; a.textContent=inS(g)?'✓':'+'; a.setAttribute('aria-label',L('Adaugă ','Add ')+g);
    a.onclick=()=>toggleOpt(g);
    c.append(q,a); row.appendChild(c)});
}
$('opt-all').onclick=()=>{const st=customStack(); optGenes().forEach(g=>{if(!st.genes.includes(g)) st.genes.push(g)}); if(st.genes.length) setStack(st); renderOpts(); toast(L('Am adăugat toate opțiunile','Added all options'))};

