function ic(k){return ICONS[k]?'<svg class="ic" viewBox="0 0 24 24" aria-hidden="true">'+ICONS[k]+'</svg>':''}
document.querySelectorAll('[data-ic]').forEach(e=>{e.innerHTML=ic(e.dataset.ic)});
/* ================== MĂRIME ESTIMATĂ FIȘIER ================== */
function updSize(exact){
  const el=$('size-info'); if(!el) return; const hi=$('qual').value==='hi', sr=hi?48000:44100, by=hi?3:2, dur=+$('dur').value;
  let sec=dur, known=dur>0;
  if(S.stack&&S.stack.genes&&S.stack.genes.length){ try{sec=buildNotes(S.stack.genes,+$('bpm').value,dur).total; known=true}catch(e){} }
  const fmtMB=b=>b>=1048576?(b/1048576).toFixed(1).replace('.',LANG==='ro'?',':'.')+' MB':Math.round(b/1024)+' KB';
  el.innerHTML=known? L('Mărime fișier .wav: ','.wav file size: ')+'<b>~'+fmtMB(44+sec*sr*by)+'</b> ('+fmt(sec)+' min, '+(hi?'48 kHz / 24-bit':'44,1 kHz / 16-bit')+')'
    : L('Mărimea fișierului apare după ce alegi o stivă.','The file size appears after you choose a stack.');
}
['qual','dur','bpm'].forEach(id=>$(id).addEventListener('change',()=>updSize()));
{ const _ss=setStack; setStack=function(){const r=_ss.apply(this,arguments); updSize(); return r}; }
updSize();

/* ================== SETĂRI APLICATE LIVE ================== */
function liveRegen(){
  if(!S.lastGenes||!S.wav) return;
  const was=!audio.paused, pos=audio.currentTime||0, keep=S.playing;
  generate(S.lastGenes,false); S.playing=keep;
  audio.addEventListener('loadedmetadata',()=>{ try{ if(pos>0&&pos<audio.duration-0.5) audio.currentTime=pos }catch(e){}
    if(was){const p=audio.play(); if(p&&p.catch) p.catch(()=>{})} },{once:true});
  toast(L('Setare aplicată pe sunet','Setting applied to the sound'));
}
['tune','timbre','dur','qual'].forEach(id=>$(id).addEventListener('change',liveRegen));
